import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";import"./chunks/assets.DfIShTN7.js";var i=JSON.parse(`{"title":"El método agéntico","description":"Cómo Reza Bazdar envía software de producción con OpenCode, Codex, Claude Code y el agente Hermes — brief, generar, revisar, desplegar.","frontmatter":{"title":"El método agéntico","description":"Cómo Reza Bazdar envía software de producción con OpenCode, Codex, Claude Code y el agente Hermes — brief, generar, revisar, desplegar."},"headers":[],"relativePath":"es/about/how-i-work/index.md","filePath":"es/about/how-i-work/index.md"}`),a={name:`es/about/how-i-work/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="el-metodo-agentico" tabindex="-1">El método agéntico <a class="header-anchor" href="#el-metodo-agentico" aria-label="Permalink to “El método agéntico”">​</a></h1><p>Practico la <strong>codificación agéntica</strong> como disciplina diaria, no como truco de demostración. Mis herramientas diarias son <strong>OpenCode</strong>, <strong>OpenAI Codex</strong> y <strong>Claude Code</strong>, orquestadas por <strong>Hermes Agent</strong> — mi propia infraestructura de agentes autoalojada. Juntos se comportan como un pequeño equipo de ingeniería que nunca duerme, y yo soy su líder técnico.</p><p>Esto no es &quot;la IA lo escribe todo mientras yo miro&quot;. Delegar en agentes es una habilidad con la misma seriedad que escribir código a mano: aprendes a escribir especificaciones en lugar de funciones, a diseñar puntos de revisión en lugar de sesiones de depuración, y a auditar diffs como un ingeniero senior revisa a un junior — con respeto, pero sin piedad.</p><h2 id="el-ciclo-que-entrega-funciones" tabindex="-1">El ciclo que entrega funciones <a class="header-anchor" href="#el-ciclo-que-entrega-funciones" aria-label="Permalink to “El ciclo que entrega funciones”">​</a></h2><ol><li><strong>Informar a los agentes.</strong> Convierto la idea en una especificación precisa y comprobable: alcance, casos límite, criterios de aceptación. Un buen brief es el 80% del resultado.</li><li><strong>Generar e iterar.</strong> Los agentes implementan en paralelo — uno refactoriza, otro escribe tests, un tercero prepara el despliegue. Yo dirijo, desbloqueo y reajusto el alcance en tiempo real.</li><li><strong>Revisión humana.</strong> Audito cada diff yo mismo: seguridad, arquitectura, casos límite, rendimiento. El output del agente es una propuesta, nunca una promesa.</li><li><strong>Desplegar y monitorear.</strong> Publicar al borde, vigilar logs y métricas, y devolver cada lección al siguiente brief.</li></ol><figure class="concept-illustration"><img src="/Usf/assets/img/agentic-loop.svg" alt="El ciclo agéntico de cuatro pasos: brief, generar, revisar, desplegar" loading="lazy"><figcaption>El ciclo que ejecuto a diario — con humanos exactamente donde importa el juicio.</figcaption></figure><h2 id="por-que-es-una-habilidad-de-ingenieria-real" tabindex="-1">Por qué es una habilidad de ingeniería real <a class="header-anchor" href="#por-que-es-una-habilidad-de-ingenieria-real" aria-label="Permalink to “Por qué es una habilidad de ingeniería real”">​</a></h2><p>Dirigir agentes expone debilidades que la velocidad de tecleo nunca revelará. Si tu arquitectura es vaga, los agentes amplifican la vaguedad. Si tus tests son débiles, los agentes los pasan con total confianza. Si tu spec es ambigua, recibes diez interpretaciones creativas que no pediste. Trabajar así me obliga a pensar con más claridad que el desarrollo tradicional — los agentes son espejos, y no tienen piedad.</p><blockquote><p>La habilidad de la próxima década no es teclear más rápido — es dirigir agentes inteligentes con la precisión de un ingeniero senior y el gusto de un diseñador de producto.</p></blockquote><p>Cada proyecto de este sitio — desde el kit de red <a href="/Usf/es/projects/netpilot/">NetPilot</a> hasta este mismo portafolio — fue diseñado, revisado y enviado por ese ciclo. La sección de <a href="/Usf/es/agentic/overview/">Codificación agéntica</a> desglosa cada herramienta que uso.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};